void graphics_diagnostic__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L, u32 format,
                                               u32 return_pc, unsigned argument_reg) {
    if (!R(2)) {
        set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(format));
        set_reg__credits_roll__stream1_exe(c, 4, format);
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0x4));
        load_word__credits_roll__stream1_exe(c, 2, L->data + 0x4);
        NC_POLL(c, 1);
        u32 diagnostic = R(2);
        R(31) = return_pc;
        R(5) = R(argument_reg);
        NC_POLL(c, 2);
        nc_call(c, diagnostic);
    }
}

void build_draw_env_packet__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L, u32 resume) {
    set_reg__credits_roll__stream1_exe(c, 16, R(17) + 28); /* embedded packet */
    set_reg__credits_roll__stream1_exe(c, 4, R(16));
    R(31) = resume;
    R(5) = R(17);
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    nc_call(c, L->code + 0x1db8); /* SetDrawEnv */

    set_reg__credits_roll__stream1_exe(c, 4, 0x00ff0000);
    set_reg__credits_roll__stream1_exe(c, 4, 0x00ffffff);
    set_reg__credits_roll__stream1_exe(c, 5, R(16));
    set_reg__credits_roll__stream1_exe(c, 6, 64); /* packet bytes copied by the queue */
}

/* Merge the link address into the packet header, enqueue it and cache the DRAWENV. */
void submit_draw_env__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L, unsigned debug_reg,
                                           u32 queue_resume, u32 copy_resume) {
    set_reg__credits_roll__stream1_exe(c, 3, gpu_hi(L->data));
    load_word__credits_roll__stream1_exe(c, 3, L->data);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) | R(4));
    MEM_W32(R(17) + 28, R(2));
    NC_POLL(c, NC_INSN_CYCLES);
    load_word__credits_roll__stream1_exe(c, 4, R(3) + 0x18);
    load_word__credits_roll__stream1_exe(c, 2, R(3) + 8);
    NC_POLL(c, NC_INSN_CYCLES);
    u32 enqueue = R(2);
    R(31) = queue_resume;
    R(7) = 0;
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    nc_call(c, enqueue);

    set_reg__credits_roll__stream1_exe(c, 4, R(debug_reg) + 14);
    set_reg__credits_roll__stream1_exe(c, 5, R(17));
    R(31) = copy_resume;
    R(6) = 92; /* full DRAWENV, including the packet */
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    nc_call(c, L->memcpy); /* memcpy */
}

bool display_rect_changed__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L,
                                                unsigned offset) {
    for (unsigned i = offset; i < offset + 8; i += 2) {
        u32 cached = (L->data + 0x74) + i;
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(cached));
        if (i == 8)
            set_reg__credits_roll__stream1_exe(c, 2, cached);
        load_image_halfword(c, 2, cached, false);
        load_image_halfword(c, 3, R(16) + i, true);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) << 16);
        set_reg__credits_roll__stream1_exe(c, 2, (u32)((s32)R(2) >> 16));
        bool changed = R(2) != R(3);
        NC_POLL(c, 2);
        if (changed)
            return true;
    }
    return false;
}

void set_display_origin__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0x8));
    R(2) = MEM_R8(L->data + 0x8);
    NC_POLL(c, NC_LOAD_CYCLES);
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) - 1);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) < 2);
    bool wide_fields = R(2) != 0;
    NC_POLL(c, 2);
    if (wide_fields) {
        R(31) = L->code + 0x1790;
        R(4) = R(16);
        NC_POLL(c, 2);
        nc_call(c, L->code + 0x231c); /* get_dx */
        load_image_halfword(c, 3, R(16) + 2, false);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) & 0xfff);
        set_reg__credits_roll__stream1_exe(c, 3, R(3) & 0xfff);
        set_reg__credits_roll__stream1_exe(c, 3, R(3) << 12);
        set_reg__credits_roll__stream1_exe(c, 3, R(3) | R(2));
        R(2) = 0x05000000;
        NC_POLL(c, 2);
    } else {
        load_image_halfword(c, 2, R(16) + 2, false);
        load_image_halfword(c, 3, R(16), false);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) & 0x3ff);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) << 10);
        set_reg__credits_roll__stream1_exe(c, 3, R(3) & 0x3ff);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) | R(3));
        set_reg__credits_roll__stream1_exe(c, 3, 0x05000000);
    }
    set_reg__credits_roll__stream1_exe(c, 4, R(2) | R(3));
    load_gpu_global__sdk_gpu__stream1_exe(c, L, 2, L->data);
    NC_POLL(c, 1);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 16);
    NC_POLL(c, 1);
    gpu_sync_call(c, R(2), L->code + 0x17e8);
}

/* Clamp the vertical start or end to the video standard's scanline limit. */
void limit_display_scanline__sdk_gpu__stream1_exe(CPUState *c, bool end) {
    unsigned src = end ? 18 : 17, dest = end ? 3 : 4;
    u32 ntsc_max = end ? 258 : 256, pal_max = end ? 312 : 310;
    load_env_byte(c, 2, 18);
    NC_POLL(c, 1);
    bool pal = R(2) != 0;
    R(2) = (s32)R(src) <= (s32)pal_max;
    NC_POLL(c, 2);
    if (!pal)
        set_reg__credits_roll__stream1_exe(c, 2, (s32)R(src) <= (s32)ntsc_max);
    bool fits = R(2) != 0;
    NC_POLL(c, 2);
    if (fits) {
        R(dest) = R(src);
        NC_POLL(c, end && !pal ? 1 : 2);
    } else {
        load_env_byte(c, 2, 18);
        NC_POLL(c, 1);
        pal = R(2) != 0;
        R(dest) = ntsc_max;
        NC_POLL(c, 2);
        if (pal) {
            R(dest) = pal_max;
            NC_POLL(c, 2);
        }
    }
}

void send_display_range__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L, bool vertical) {
    u32 mask = vertical ? 0x3ff : 0xfff;
    set_reg__credits_roll__stream1_exe(c, 2, R(vertical ? 18 : 6) & mask);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) << (vertical ? 10 : 12));
    set_reg__credits_roll__stream1_exe(c, 4, R(vertical ? 17 : 5) & mask);
    set_reg__credits_roll__stream1_exe(c, 3, vertical ? 0x07000000 : 0x06000000);
    load_gpu_global__sdk_gpu__stream1_exe(c, L, 5, L->data);
    set_reg__credits_roll__stream1_exe(c, 4, R(4) | R(3));
    load_word__credits_roll__stream1_exe(c, 3, R(5) + 16);
    NC_POLL(c, 1);
    u32 driver = R(3);
    R(31) = vertical ? (L->code + 0x1a20) : (L->code + 0x19f4);
    R(4) |= R(2);
    NC_POLL(c, 2);
    nc_call(c, driver);
}

void set_display_ranges__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    gpu_sync_call(c, L->code + 0x124, L->code + 0x1864); /* GetVideoMode */
    load_image_halfword(c, 3, R(16) + 8, true);
    MEM_W8(R(16) + 18, (u8)R(2));
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 2, R(3) << 2);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) + R(3));
    set_reg__credits_roll__stream1_exe(c, 2, R(2) << 1);
    set_reg__credits_roll__stream1_exe(c, 5, R(2) + 608); /* horizontal start in GPU clock units */
    load_env_byte(c, 2, 18);
    load_image_halfword(c, 4, R(16) + 10, true);
    bool pal = R(2) != 0;
    R(17) = R(4) + 19;
    NC_POLL(c, 2);
    if (!pal)
        set_reg__credits_roll__stream1_exe(c, 17, R(4) + 16);
    load_image_halfword(c, 3, R(16) + 12, true);
    NC_POLL(c, 1);
    bool width = R(3) != 0;
    R(2) = R(3) << 2;
    NC_POLL(c, 2);
    if (width) {
        set_reg__credits_roll__stream1_exe(c, 2, R(2) + R(3));
        set_reg__credits_roll__stream1_exe(c, 2, R(2) << 1);
        R(6) = R(5) + R(2);
        NC_POLL(c, 2);
    } else {
        set_reg__credits_roll__stream1_exe(c, 6, R(5) + 2560);
    }
    load_image_halfword(c, 2, R(16) + 14, true);
    NC_POLL(c, 1);
    bool height = R(2) != 0;
    R(18) = R(17) + R(2);
    NC_POLL(c, 2);
    if (!height)
        set_reg__credits_roll__stream1_exe(c, 18, R(17) + 240);

    set_reg__credits_roll__stream1_exe(c, 2, (s32)R(5) < 500);
    bool low = R(2) != 0;
    R(4) = 500;
    NC_POLL(c, 2);
    if (low) {
        set_reg__credits_roll__stream1_exe(c, 5, R(4));
    } else {
        set_reg__credits_roll__stream1_exe(c, 4, R(5));
        set_reg__credits_roll__stream1_exe(c, 2, (s32)R(4) <= 3290);
        bool fits = R(2) != 0;
        R(5) = R(4);
        NC_POLL(c, 2);
        if (!fits) {
            set_reg__credits_roll__stream1_exe(c, 4, 3290);
            set_reg__credits_roll__stream1_exe(c, 5, R(4));
        }
    }
    set_reg__credits_roll__stream1_exe(c, 3, R(5) + 80);
    set_reg__credits_roll__stream1_exe(c, 2, (s32)R(6) < (s32)R(3));
    bool narrow = R(2) != 0;
    R(2) = (s32)R(17) < 16;
    NC_POLL(c, 2);
    if (!narrow) {
        set_reg__credits_roll__stream1_exe(c, 3, R(6));
        set_reg__credits_roll__stream1_exe(c, 2, (s32)R(3) <= 3290);
        bool fits = R(2) != 0;
        R(2) = (s32)R(17) < 16;
        NC_POLL(c, 2);
        if (!fits)
            set_reg__credits_roll__stream1_exe(c, 3, 3290);
    }
    low = R(2) != 0;
    R(6) = R(3);
    NC_POLL(c, 2);
    if (low)
        set_reg__credits_roll__stream1_exe(c, 4, 16);
    else
        limit_display_scanline__sdk_gpu__stream1_exe(c, false);
    set_reg__credits_roll__stream1_exe(c, 17, R(4));
    set_reg__credits_roll__stream1_exe(c, 3, R(17) + 2);
    set_reg__credits_roll__stream1_exe(c, 2, (s32)R(18) < (s32)R(3));
    bool short_range = R(2) != 0;
    NC_POLL(c, 2);
    if (!short_range)
        limit_display_scanline__sdk_gpu__stream1_exe(c, true);
    set_reg__credits_roll__stream1_exe(c, 18, R(3));
    send_display_range__sdk_gpu__stream1_exe(c, L, false);
    send_display_range__sdk_gpu__stream1_exe(c, L, true);
}

void set_display_resolution__sdk_gpu__stream1_exe(CPUState *c) {
    load_image_halfword(c, 3, R(16) + 4, true);
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 2, (s32)R(3) <= 280);
    bool small = R(2) != 0;
    R(2) = (s32)R(3) <= 352;
    NC_POLL(c, 2);
    if (!small) {
        bool medium = R(2) != 0;
        R(2) = (s32)R(3) <= 400;
        NC_POLL(c, 2);
        if (medium) {
            R(19) |= 1;
            NC_POLL(c, 2);
        } else {
            bool special = R(2) != 0;
            R(2) = (s32)R(3) <= 560;
            NC_POLL(c, 2);
            if (special) {
                R(19) |= 64;
                NC_POLL(c, 2);
            } else {
                bool wide = R(2) != 0;
                NC_POLL(c, 2);
                R(19) |= wide ? 2 : 3;
                NC_POLL(c, wide ? 2 : 1);
            }
        }
    }
    load_env_byte(c, 2, 18);
    load_image_halfword(c, 3, R(16) + 6, true);
    bool pal = R(2) != 0;
    R(2) = (s32)R(3) <= 288;
    NC_POLL(c, 2);
    if (!pal)
        set_reg__credits_roll__stream1_exe(c, 2, (s32)R(3) <= 256);
    bool tall = !R(2);
    NC_POLL(c, 2);
    if (tall)
        set_reg__credits_roll__stream1_exe(c, 19, R(19) | 0x24);
}

void set_display_mode__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    gpu_sync_call(c, L->code + 0x124, L->code + 0x1ab0);
    MEM_W8(R(16) + 18, (u8)R(2));
    NC_POLL(c, 1);
    load_env_byte(c, 3, 18);
    set_reg__credits_roll__stream1_exe(c, 2, 1);
    bool pal = R(3) == R(2);
    NC_POLL(c, 2);
    if (pal)
        set_reg__credits_roll__stream1_exe(c, 19, R(19) | 8);
    for (unsigned i = 0; i < 3; i++) {
        if (i < 2) {
            load_env_byte(c, 2, 17 - i); /* RGB24 and interlace */
        } else {
            set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0xb));
            set_reg__credits_roll__stream1_exe(c, 2, L->data + 0xb);
            R(2) = MEM_R8(R(2)); /* reverse display */
            NC_POLL(c, NC_LOAD_CYCLES);
        }
        NC_POLL(c, 1);
        bool enabled = R(2) != 0;
        NC_POLL(c, 2);
        if (enabled)
            set_reg__credits_roll__stream1_exe(c, 19, R(19) | (i == 2 ? 0x80 : 0x10u << i));
    }
    set_display_resolution__sdk_gpu__stream1_exe(c);
    load_gpu_global__sdk_gpu__stream1_exe(c, L, 2, L->data);
    NC_POLL(c, 1);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 16);
    NC_POLL(c, 1);
    u32 driver = R(2);
    R(31) = L->code + 0x1b90;
    R(4) = R(19);
    NC_POLL(c, 2);
    nc_call(c, driver);
}

bool sdk_gpu_put_display_env__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 9)
        return false;
    R(29) -= 40;
    MEM_W32(R(29) + 16, R(16));
    R(16) = R(4);
    R(2) = gpu_hi(L->data + 0xa);
    R(2) = L->data + 0xa;
    MEM_W32(R(29) + 32, R(31));
    MEM_W32(R(29) + 28, R(19));
    MEM_W32(R(29) + 24, R(18));
    MEM_W32(R(29) + 20, R(17));
    c->budget -= 9;
    R(2) = MEM_R8(R(2));
    NC_POLL(c, NC_LOAD_CYCLES);
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) < 2);
    bool debug = !R(2);
    R(19) = 0x08000000;
    NC_POLL(c, 2);
    if (debug) {
        set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(L->strings + 0x2a0));
        set_reg__credits_roll__stream1_exe(c, 4, L->strings + 0x2a0);
        load_gpu_global__sdk_gpu__stream1_exe(c, L, 2, L->data + 0x4);
        NC_POLL(c, 1);
        u32 printer = R(2);
        R(31) = L->code + 0x176c;
        R(5) = R(16);
        NC_POLL(c, 2);
        nc_call(c, printer);
    }
    set_display_origin__sdk_gpu__stream1_exe(c, L);
    if (display_rect_changed__sdk_gpu__stream1_exe(c, L, 8))
        set_display_ranges__sdk_gpu__stream1_exe(c, L);
    load_gpu_global__sdk_gpu__stream1_exe(c, L, 3, L->data + 0x84);
    load_word__credits_roll__stream1_exe(c, 2, R(16) + 16);
    NC_POLL(c, 1);
    bool changed = R(3) != R(2);
    NC_POLL(c, 2);
    if (changed || display_rect_changed__sdk_gpu__stream1_exe(c, L, 0))
        set_display_mode__sdk_gpu__stream1_exe(c, L);
    set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(L->data + 0x74));
    set_reg__credits_roll__stream1_exe(c, 4, L->data + 0x74);
    set_reg__credits_roll__stream1_exe(c, 5, R(16));
    R(31) = L->code + 0x1ba4;
    R(6) = 20;
    NC_POLL(c, 2);
    nc_call(c, L->memcpy);
    set_reg__credits_roll__stream1_exe(c, 2, R(16));
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 32);
    for (unsigned reg = 19; reg >= 16; reg--)
        load_word__credits_roll__stream1_exe(c, reg, R(29) + 16 + 4 * (reg - 16));
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 40);
    NC_POLL(c, 2);
    return true;
}

/* Build the embedded draw packet, submit it and save the active DRAWENV. */
bool sdk_gpu_put_draw_env__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 11 * NC_INSN_CYCLES + NC_LOAD_CYCLES)
        return false;
    R(29) -= 32;
    c->budget--;
    MEM_W32(R(29) + 24, R(18));
    R(18) = L->data + 0xa;
    c->budget -= 3;
    MEM_W32(R(29) + 28, R(31));
    c->budget--;
    MEM_W32(R(29) + 20, R(17));
    c->budget--;
    MEM_W32(R(29) + 16, R(16));
    c->budget--;
    R(2) = MEM_R8(R(18)) < 2;
    R(17) = R(4); /* environment */
    c->budget -= NC_LOAD_CYCLES + 4;
    graphics_diagnostic__sdk_gpu__stream1_exe(c, L, L->strings + 0x26c, L->code + 0x158c, 17);

    build_draw_env_packet__sdk_gpu__stream1_exe(c, L, L->code + 0x159c);
    load_word__credits_roll__stream1_exe(c, 2, R(17) + 28);
    submit_draw_env__sdk_gpu__stream1_exe(c, L, 18, L->code + 0x15d4, L->code + 0x15e4);
    set_reg__credits_roll__stream1_exe(c, 2, R(17));
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 28);
    load_word__credits_roll__stream1_exe(c, 18, R(29) + 24);
    load_word__credits_roll__stream1_exe(c, 17, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 32);
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    return true;
}

/* Prepend the draw environment packet to the supplied ordering table. */
bool sdk_gpu_draw_otag_env__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 13 * NC_INSN_CYCLES + NC_LOAD_CYCLES)
        return false;
    R(29) -= 40;
    c->budget--;
    MEM_W32(R(29) + 24, R(18));
    R(18) = R(4); /* ordering table */
    c->budget -= 2;
    MEM_W32(R(29) + 28, R(19));
    R(19) = L->data + 0xa;
    c->budget -= 3;
    MEM_W32(R(29) + 32, R(31));
    c->budget--;
    MEM_W32(R(29) + 20, R(17));
    c->budget--;
    MEM_W32(R(29) + 16, R(16));
    c->budget--;
    R(2) = MEM_R8(R(19)) < 2;
    R(17) = R(5); /* environment */
    c->budget -= NC_LOAD_CYCLES + 4;
    if (!R(2)) {
        set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(L->strings + 0x284));
        set_reg__credits_roll__stream1_exe(c, 4, L->strings + 0x284);
        set_reg__credits_roll__stream1_exe(c, 5, R(18));
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0x4));
        load_word__credits_roll__stream1_exe(c, 2, L->data + 0x4);
        NC_POLL(c, NC_INSN_CYCLES);
        u32 diagnostic = R(2);
        R(31) = L->code + 0x165c;
        R(6) = R(17);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, diagnostic);
    }
    build_draw_env_packet__sdk_gpu__stream1_exe(c, L, L->code + 0x166c);
    set_reg__credits_roll__stream1_exe(c, 3, 0xff000000);
    load_word__credits_roll__stream1_exe(c, 2, R(17) + 28);
    set_reg__credits_roll__stream1_exe(c, 4, R(18) & R(4)); /* 24-bit ordering table address */
    set_reg__credits_roll__stream1_exe(c, 2, R(2) & R(3));  /* retain the packet length */
    submit_draw_env__sdk_gpu__stream1_exe(c, L, 19, L->code + 0x16b0, L->code + 0x16c0);
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 32);
    load_word__credits_roll__stream1_exe(c, 19, R(29) + 28);
    load_word__credits_roll__stream1_exe(c, 18, R(29) + 24);
    load_word__credits_roll__stream1_exe(c, 17, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 40);
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    return true;
}

/* DrawOTag queues the active driver's DMA-chain method with the ordering table. */
bool sdk_gpu_draw_otag__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 10)
        return false;
    graphics_debug_prologue(c, L);
    graphics_diagnostic__sdk_gpu__stream1_exe(c, L, L->strings + 0x258, L->code + 0x1508, 16);
    set_reg__credits_roll__stream1_exe(c, 5, R(16));
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data));
    load_word__credits_roll__stream1_exe(c, 2, L->data);
    set_reg__credits_roll__stream1_exe(c, 6, 0);
    load_word__credits_roll__stream1_exe(c, 4, R(2) + 0x18);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 8);
    NC_POLL(c, 1);
    u32 enqueue = R(2);
    R(31) = L->code + 0x152c;
    R(7) = 0;
    NC_POLL(c, 2);
    nc_call(c, enqueue);

    load_word__credits_roll__stream1_exe(c, 31, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 24);
    NC_POLL(c, 2);
    return true;
}

bool sdk_gpu_draw_sync_callback__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 10)
        return false;
    graphics_debug_prologue(c, L);
    if (!R(2)) {
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 4));
        load_word__credits_roll__stream1_exe(c, 2, R(2) + gpu_lo(L->data + 4));
        set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(L->strings + 0x190));
        set_reg__credits_roll__stream1_exe(c, 4, L->strings + 0x190);
        u32 diagnostic = R(2);
        R(31) = L->code + 0xe0c;
        R(5) = R(16);
        NC_POLL(c, 2 * NC_INSN_CYCLES);
        nc_call(c, diagnostic);
    }

    /* Read the previous handler after the diagnostic returns. */
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0x14));
    load_word__credits_roll__stream1_exe(c, 2, R(2) + gpu_lo(L->data + 0x14));
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0x14));
    MEM_W32(R(1) + gpu_lo(L->data + 0x14), R(16));
    NC_POLL(c, NC_INSN_CYCLES);
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 24);
    NC_POLL(c, 2 * NC_INSN_CYCLES);
    return true;
}

bool sdk_gpu_draw_sync__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 10)
        return false;
    graphics_debug_prologue(c, L);
    graphics_diagnostic__sdk_gpu__stream1_exe(c, L, L->strings + 0x1c0, L->code + 0xf08, 16);

    /* The diagnostic can replace the active driver before this lookup. */
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data));
    load_word__credits_roll__stream1_exe(c, 2, L->data);
    NC_POLL(c, 1);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 0x3c);
    NC_POLL(c, 1);
    u32 sync = R(2);
    R(31) = L->code + 0xf24;
    R(4) = R(16);
    NC_POLL(c, 2);
    nc_call(c, sync);
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 24);
    NC_POLL(c, 2);
    return true;
}

void initialize_graphics_state__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    set_reg__credits_roll__stream1_exe(c, 4, gpu_hi(L->strings + 0x104));
    set_reg__credits_roll__stream1_exe(c, 4, L->strings + 0x104);
    set_reg__credits_roll__stream1_exe(c, 5, gpu_hi(L->data - 0x40));
    set_reg__credits_roll__stream1_exe(c, 5, L->data - 0x40);
    set_reg__credits_roll__stream1_exe(c, 16, gpu_hi(L->data + 0x8));
    set_reg__credits_roll__stream1_exe(c, 16, L->data + 0x8);
    R(31) = L->code + 0xa74;
    R(6) = R(16);
    NC_POLL(c, 2);
    nc_call(c, L->printf); /* printf */
    set_reg__credits_roll__stream1_exe(c, 4, R(16));
    set_reg__credits_roll__stream1_exe(c, 5, 0);
    fill_graphics_state(c, L, 0x80, L->code + 0xa84);
    gpu_sync_call(c, L->reset_callback, L->code + 0xa8c); /* ResetCallback */
    set_reg__credits_roll__stream1_exe(c, 2, 0x00ff0000);
    load_gpu_global__sdk_gpu__stream1_exe(c, L, 4, L->data);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) | 0xffff);
    R(31) = L->code + 0xaa4;
    R(4) &= R(2);
    NC_POLL(c, 2);
    nc_call(c, L->code + 0x3890); /* GPU_cw */
    R(31) = L->code + 0xaac;
    R(4) = R(17);
    NC_POLL(c, 2);
    nc_call(c, L->code + 0x3344);

    /* The reset result selects the VRAM width and height tables by low byte. */
    set_reg__credits_roll__stream1_exe(c, 4, R(16) + 16);
    MEM_W8(R(16), (u8)R(2));
    NC_POLL(c, 1);
    R(2) = MEM_R8(R(16));
    NC_POLL(c, NC_LOAD_CYCLES);
    set_reg__credits_roll__stream1_exe(c, 3, 1);
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0x9));
    MEM_W8(L->data + 0x9, (u8)R(3));
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) << 2);
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0x88));
    set_reg__credits_roll__stream1_exe(c, 1, R(1) + R(2));
    R(3) = MEM_R16(R(1) + gpu_lo(L->data + 0x88));
    NC_POLL(c, NC_LOAD_CYCLES);
    R(2) = MEM_R8(R(16));
    NC_POLL(c, NC_LOAD_CYCLES);
    set_reg__credits_roll__stream1_exe(c, 5, UINT32_MAX);
    set_reg__credits_roll__stream1_exe(c, 2, R(2) << 2);
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0xc));
    MEM_W16(L->data + 0xc, (u16)R(3));
    NC_POLL(c, 1);
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0x9c));
    set_reg__credits_roll__stream1_exe(c, 1, R(1) + R(2));
    R(2) = MEM_R16(R(1) + gpu_lo(L->data + 0x9c));
    NC_POLL(c, NC_LOAD_CYCLES);
    set_reg__credits_roll__stream1_exe(c, 1, gpu_hi(L->data + 0xe));
    MEM_W16(L->data + 0xe, (u16)R(2));
    NC_POLL(c, 1);
    fill_graphics_state(c, L, 0x5c, L->code + 0xb04);
    set_reg__credits_roll__stream1_exe(c, 4, R(16) + 0x6c);
    set_reg__credits_roll__stream1_exe(c, 5, UINT32_MAX);
    fill_graphics_state(c, L, 0x14, L->code + 0xb14);
    R(2) = MEM_R8(R(16));
    NC_POLL(c, NC_LOAD_CYCLES);
    NC_POLL(c, 2);
}

bool sdk_gpu_reset_graph__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    if (c->budget <= 7)
        return false;
    R(29) -= 32;
    c->budget--;
    MEM_W32(R(29) + 20, R(17));
    R(17) = R(4);
    R(3) = R(17) & 7;
    c->budget -= 3;
    MEM_W32(R(29) + 24, R(31));
    c->budget--;
    bool initialize = R(3) == 0;
    MEM_W32(R(29) + 16, R(16));
    c->budget -= 2;
    if (!initialize) {
        set_reg__credits_roll__stream1_exe(c, 2, 3);
        initialize = R(3) == R(2);
        NC_POLL(c, 2);
    }
    if (initialize) {
        initialize_graphics_state__sdk_gpu__stream1_exe(c, L);
    } else {
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0xa));
        R(2) = MEM_R8(L->data + 0xa);
        NC_POLL(c, NC_LOAD_CYCLES);
        NC_POLL(c, 1);
        set_reg__credits_roll__stream1_exe(c, 2, R(2) < 2);
        NC_POLL(c, 2);
        graphics_diagnostic__sdk_gpu__stream1_exe(c, L, L->strings + 0x124, L->code + 0xb54, 17);
        load_gpu_global__sdk_gpu__stream1_exe(c, L, 2, L->data);
        NC_POLL(c, 1);
        load_word__credits_roll__stream1_exe(c, 2, R(2) + 0x34);
        NC_POLL(c, 1);
        u32 reset = R(2);
        R(31) = L->code + 0xb70;
        R(4) = 1;
        NC_POLL(c, 2);
        nc_call(c, reset);
    }
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 24);
    load_word__credits_roll__stream1_exe(c, 17, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 32);
    NC_POLL(c, 2);
    return true;
}

/* Set the GPU display-mode reverse bit and return the previous flag byte. */
bool sdk_gpu_set_graph_reverse__sdk_gpu__stream1_exe(CPUState *c, const NcGpuLayout *L) {
    const int entry_cycles = 11 * NC_INSN_CYCLES + 2 * NC_LOAD_CYCLES;
    if (c->budget <= entry_cycles)
        return false;
    c->budget--;
    R(2) = MEM_R8(L->data + 0xa);
    R(29) -= 32;
    c->budget -= NC_LOAD_CYCLES + 1;
    MEM_W32(R(29) + 20, R(17));
    c->budget--;
    MEM_W32(R(29) + 16, R(16));
    R(16) = L->data + 0xb;
    c->budget -= 3;
    MEM_W32(R(29) + 28, R(31));
    c->budget--;
    MEM_W32(R(29) + 24, R(18));
    c->budget--;
    R(18) = MEM_R8(R(16));
    R(2) = R(2) < 2;
    R(17) = R(4);
    c->budget -= NC_LOAD_CYCLES + 3;
    graphics_diagnostic__sdk_gpu__stream1_exe(c, L, L->strings + 0x138, L->code + 0xbd8, 17);

    /* Query GPU parameter 8, then combine it with the current reverse flag. */
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data));
    load_word__credits_roll__stream1_exe(c, 2, L->data);
    MEM_W8(R(16), (u8)R(17));
    NC_POLL(c, 1);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 0x28);
    NC_POLL(c, 1);
    R(31) = L->code + 0xbf4;
    R(4) = 8;
    NC_POLL(c, 2);
    nc_call(c, R(2));
    R(3) = MEM_R8(R(16));
    NC_POLL(c, NC_LOAD_CYCLES);
    NC_POLL(c, 1);
    bool reverse = R(3) != 0;
    R(4) = R(2);
    NC_POLL(c, 2);
    set_reg__credits_roll__stream1_exe(c, 2, 0x08000000);
    if (reverse) {
        R(2) |= 0x80;
        NC_POLL(c, 2);
    }
    set_reg__credits_roll__stream1_exe(c, 4, R(4) | R(2));
    set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data));
    load_word__credits_roll__stream1_exe(c, 2, L->data);
    NC_POLL(c, 1);
    load_word__credits_roll__stream1_exe(c, 2, R(2) + 0x10);
    NC_POLL(c, 1);
    R(31) = L->code + 0xc34;
    NC_POLL(c, 2);
    nc_call(c, R(2));

    /* Graphics type 2 needs a second control command. */
    set_reg__credits_roll__stream1_exe(c, 3, gpu_hi(L->data + 0x8));
    R(3) = MEM_R8(L->data + 0x8);
    NC_POLL(c, NC_LOAD_CYCLES);
    set_reg__credits_roll__stream1_exe(c, 2, 2);
    bool extra_command = R(3) == R(2);
    R(2) = R(18);
    NC_POLL(c, 2);
    if (extra_command) {
        set_reg__credits_roll__stream1_exe(c, 4, 0x20000000);
        set_reg__credits_roll__stream1_exe(c, 2, gpu_hi(L->data + 0xb));
        R(2) = MEM_R8(L->data + 0xb);
        NC_POLL(c, NC_LOAD_CYCLES);
        set_reg__credits_roll__stream1_exe(c, 3, gpu_hi(L->data));
        load_word__credits_roll__stream1_exe(c, 3, L->data);
        reverse = R(2) != 0;
        R(4) = 0x20000504;
        NC_POLL(c, 2);
        if (reverse) {
            set_reg__credits_roll__stream1_exe(c, 4, 0x20000000);
            set_reg__credits_roll__stream1_exe(c, 4, 0x20000501);
        }
        load_word__credits_roll__stream1_exe(c, 2, R(3) + 0x10);
        NC_POLL(c, 1);
        R(31) = L->code + 0xc7c;
        NC_POLL(c, 2);
        nc_call(c, R(2));
        set_reg__credits_roll__stream1_exe(c, 2, R(18));
    }
    load_word__credits_roll__stream1_exe(c, 31, R(29) + 28);
    load_word__credits_roll__stream1_exe(c, 18, R(29) + 24);
    load_word__credits_roll__stream1_exe(c, 17, R(29) + 20);
    load_word__credits_roll__stream1_exe(c, 16, R(29) + 16);
    set_reg__credits_roll__stream1_exe(c, 29, R(29) + 32);
    NC_POLL(c, 2);
    return true;
}
